const input = $input.first().json;

const topics = input.topic_list?.topics || [];

const results = [];

for (const topic of topics) {
  const title = String(topic.title || "");
  const text = title.toLowerCase();

  const isWorkflowRelated =
    text.includes("workflow") ||
    text.includes("automation") ||
    text.includes("ai agent") ||
    text.includes("agent") ||
    text.includes("gmail") ||
    text.includes("whatsapp") ||
    text.includes("google sheets") ||
    text.includes("slack") ||
    text.includes("crm") ||
    text.includes("rag") ||
    text.includes("api");

  if (!isWorkflowRelated) {
    continue;
  }

  results.push({
    json: {
      forum_topic_id: topic.id,

      title: topic.title || null,

      slug: topic.slug || null,

      url: topic.slug
        ? `https://community.n8n.io/t/${topic.slug}/${topic.id}`
        : null,

      views: Number(topic.views || 0),

      replies: Number(
        topic.reply_count ||
        topic.posts_count ||
        0
      ),

      likes: Number(
        topic.like_count ||
        0
      ),

      created_at: topic.created_at || null,

      last_posted_at: topic.last_posted_at || null,

      source_platform: "n8n_forum",

      collected_at: new Date().toISOString()
    }
  });
}

return results;

const items = $input.all();

if (items.length === 0) {
  return [];
}

const maxViews = Math.max(
  ...items.map(item => Math.log1p(Number(item.json.views || 0)))
);

const maxReplies = Math.max(
  ...items.map(item => Number(item.json.replies || 0))
);

const maxLikes = Math.max(
  ...items.map(item => Number(item.json.likes || 0))
);

return items.map(item => {
  const data = item.json;

  const views = Number(data.views || 0);
  const replies = Number(data.replies || 0);
  const likes = Number(data.likes || 0);

  const viewsScore =
    maxViews > 0
      ? (Math.log1p(views) / maxViews) * 100
      : 0;

  const repliesScore =
    maxReplies > 0
      ? (replies / maxReplies) * 100
      : 0;

  const likesScore =
    maxLikes > 0
      ? (likes / maxLikes) * 100
      : 0;

  const popularityScore =
    (viewsScore * 0.50) +
    (repliesScore * 0.30) +
    (likesScore * 0.20);

  return {
    json: {
      ...data,

      views_score: Number(viewsScore.toFixed(2)),
      replies_score: Number(repliesScore.toFixed(2)),
      likes_score: Number(likesScore.toFixed(2)),

      popularity_score: Number(popularityScore.toFixed(2)),

      scoring_method:
        "50% log-normalized views + 30% replies + 20% likes"
    }
  };
});

const items = $input.all();

return [
  {
    json: {
      source: "forum",
      records: items.map(item => item.json)
    }
  }
];
